// One Context per scope, shared by all closures defined in it.
function makeScope() {
  const ctx = { big: { size: 40 } };       // 'big' is context-allocated here
  const small    = { name: 'small', ctx };  // closure: ptr to the SAME ctx
  const reporter = { name: 'reporter', ctx };// sibling: forced 'big' into ctx
  return { small, reporter, ctx };
}

// Is 'big' reachable? Only if the kept closure's ctx slot still points at it.
function bigReachable(keptClosure) {
  return keptClosure.ctx.big !== null;
}

const scope = makeScope();
// Keep only 'small'; drop 'reporter'. 'small' never reads big, yet shares ctx.
const before = bigReachable(scope.small);

// FIX: null the slot in the shared Context after last real use.
scope.ctx.big = null;
const after = bigReachable(scope.small);

console.log('before=' + before + ' after=' + after);
